              <PageLoader />
              <RouteTransitionOverlay />
              <ScrollProgress />
              <ClientOnlyComponents />
              <Navigation />
              {children}
              <Footer />
            </RouteTransitionProvider>
          </MotionProvider>
        </LocaleProvider>
      </body>
    </html>
  );
}

